class Solution:
    def oneSlip(self, s: str) -> bool:
        def pal_without(skip):
            t = s[:skip] + s[skip + 1:]
            return t == t[::-1]
        if s == s[::-1]:
            return True
        return any(pal_without(k) for k in range(len(s)))

