class Solution {
    private boolean palWithout(String s, int skip) {
        int i = 0, j = s.length() - 1;
        while (i < j) {
            if (i == skip) { i++; continue; }
            if (j == skip) { j--; continue; }
            if (s.charAt(i++) != s.charAt(j--)) return false;
        }
        return true;
    }

    public boolean oneSlip(String s) {
        if (palWithout(s, -1)) return true;
        for (int k = 0; k < s.length(); k++) if (palWithout(s, k)) return true;
        return false;
    }
}

