static bool pal_without(const char* s, int n, int skip) {
    int i = 0, j = n - 1;
    while (i < j) {
        if (i == skip) { i++; continue; }
        if (j == skip) { j--; continue; }
        if (s[i++] != s[j--]) return false;
    }
    return true;
}

bool oneSlip(char* s) {
    int n = strlen(s);
    if (pal_without(s, n, -1)) return true;
    for (int k = 0; k < n; k++) if (pal_without(s, n, k)) return true;
    return false;
}

