class Solution:
    def oneSlip(self, s: str) -> bool:
        def mirror(i, j):
            while i < j:
                if s[i] != s[j]:
                    return False
                i, j = i + 1, j - 1
            return True
        i, j = 0, len(s) - 1
        while i < j:
            if s[i] != s[j]:
                return mirror(i + 1, j) or mirror(i, j - 1)
            i, j = i + 1, j - 1
        return True

