class Solution {
    private boolean mirror(String s, int i, int j) {
        while (i < j) if (s.charAt(i++) != s.charAt(j--)) return false;
        return true;
    }

    public boolean oneSlip(String s) {
        int i = 0, j = s.length() - 1;
        while (i < j) {
            if (s.charAt(i) != s.charAt(j)) return mirror(s, i + 1, j) || mirror(s, i, j - 1);
            i++;
            j--;
        }
        return true;
    }
}

